<script setup lang="ts">
/**
 * A number field that formats and steps (`design/components/number-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/number-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/number-input'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { Icon, agentMember, useDirection } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/number-input.module.css'

export interface NumberFormat {
  style?: 'decimal' | 'percent' | 'currency'
  currency?: string
  maximumFractionDigits?: number
}

export interface NumberInputMessages {
  increment?: string
  decrement?: string
}

export interface NumberInputProps {
  ariaDescribedby?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  defaultValue?: number | null
  disabled?: boolean
  /**
   * The chart tier's format descriptor, limited to what an editable field can parse back. It
   * formats the displayed text only. The committed value is always the raw number. Raw
   * `Intl.NumberFormatOptions` are not accepted.
   */
  format?: NumberFormat
  id?: string
  invalid?: boolean
  max?: number
  /**
   * The steppers' names in the host's words.
   */
  messages?: NumberInputMessages
  /**
   * Typed values are clamped at commit. The steppers snap to the step and stop at the limits.
   */
  min?: number
  /**
   * Posts the **plain number** on a hidden input, never the formatted text.
   */
  name?: string
  placeholder?: string
  /**
   * Affixes as defined in `input.md`: strings only, muted, and `aria-hidden`. Use `format`
   * first. Affixes are for units Intl cannot format ("/mo", "per seat").
   */
  prefix?: string
  /**
   * Hides the steppers, because a value that cannot be edited cannot be stepped.
   */
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  step?: number
  suffix?: string
  /**
   * `null` is the empty field.
   */
  value?: number | null
}

defineOptions({ name: 'NumberInput', inheritAttrs: false })

const props = withDefaults(defineProps<NumberInputProps>(), {
  ariaRequired: undefined,
  disabled: false,
  invalid: false,
  readOnly: false,
  size: 'md',
})
const emit = defineEmits<{
  blur: [event: FocusEvent]
  change: [value: number | null]
  focus: [event: FocusEvent]
}>()
const uid = useId()
const committed = ref(props.value === undefined ? (props.defaultValue ?? null) : props.value)
const draft = ref('')
const control = useTemplateRef<HTMLElement>('control')
const say = computed(() => ({
  increment: 'increment value',
  decrement: 'decrease value',
  ...props.messages,
}))
const documentDirection = useDirection(() => control.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    defaultValue:
      (props.value === undefined ? props.defaultValue : props.value) === undefined
        ? undefined
        : (props.value === undefined ? props.defaultValue : props.value) === null
          ? ''
          : String(props.value === undefined ? props.defaultValue : props.value),
    min: props.min,
    max: props.max,
    step: props.step,
    formatOptions: props.format,
    disabled: props.disabled,
    readOnly: props.readOnly,
    invalid: props.invalid,
    required: props.ariaRequired,
    allowMouseWheel: false,
    ids: props.id === undefined ? undefined : { input: props.id },
    translations: { incrementLabel: say.value.increment, decrementLabel: say.value.decrement },
    onValueChange: (details) => {
      service.event.current().type === 'INPUT.CHANGE'
        ? (draft.value = details.value)
        : ['INPUT.BLUR', 'INPUT.ENTER', 'VALUE.SET', 'VALUE.CLEAR'].includes(
            service.event.current().type,
          ) ||
          ((next) => next === committed.value || ((committed.value = next), emit('change', next)))(
            Number.isNaN(details.valueAsNumber) ? null : details.valueAsNumber,
          )
    },
    onValueCommit: (details) => {
      Number.isNaN(details.valueAsNumber) && draft.value.trim() !== ''
        ? committed.value === null
          ? api.value.clearValue()
          : api.value.setValue(committed.value)
        : ((next) => next === committed.value || ((committed.value = next), emit('change', next)))(
            Number.isNaN(details.valueAsNumber) ? null : details.valueAsNumber,
          )
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const effect1 = () => {
  props.value === undefined ||
    props.value === committed.value ||
    ((committed.value = props.value),
    props.value === null ? api.value.clearValue() : api.value.setValue(props.value))
}
watch(() => [props.value, committed.value], effect1, { flush: 'post' })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'NumberInput',
    element: () => control.value,
    state: () => ({
      value: committed.value,
      disabled: props.disabled,
      invalid: props.invalid,
      readonly: props.readOnly,
    }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            if (props.readOnly) throw new Error('The field is read-only.')
            const next = Math.min(Math.max(value, props.min ?? -Infinity), props.max ?? Infinity)
            api.value.setValue(next)
            ;((next) =>
              next === committed.value || ((committed.value = next), emit('change', next)))(
              Number.isNaN(next) ? null : next,
            )
          })(),
      },
      clear: () =>
        (() => {
          if (props.readOnly) throw new Error('The field is read-only.')
          api.value.clearValue()
          ;((next) => next === committed.value || ((committed.value = next), emit('change', next)))(
            Number.isNaN(NaN) ? null : NaN,
          )
        })(),
    },
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <div
    v-bind="api.getRootProps()"
    :class="styles.field"
    :data-size="size"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    :data-readonly="readOnly ? '' : undefined"
    data-member="number-input"
    @mousedown="
      !$event
        .composedPath()
        .some(
          (node) =>
            'nodeName' in node &&
            ['BUTTON', 'A', 'INPUT', 'SELECT', 'TEXTAREA'].includes(String(node.nodeName)),
        ) && ($event.preventDefault(), api.focus())
    "
  >
    <!-- affix -->
    <span v-if="prefix !== undefined" :class="styles.affix" aria-hidden="true">
      {{ prefix }}
    </span>
    <!-- field -->
    <input
      ref="control"
      v-bind="api.getInputProps()"
      :class="styles.input"
      :name="undefined"
      :placeholder="placeholder"
      :role="undefined"
      :aria-roledescription="undefined"
      :aria-valuemin="undefined"
      :aria-valuemax="undefined"
      :aria-valuenow="undefined"
      :aria-valuetext="undefined"
      :aria-label="ariaLabel"
      :aria-labelledby="ariaLabelledby"
      :aria-describedby="ariaDescribedby"
      :aria-required="ariaRequired"
      @blur="emit('blur', $event)"
      @focus="emit('focus', $event)"
    />
    <!-- affix -->
    <span v-if="suffix !== undefined" :class="styles.affix" aria-hidden="true">
      {{ suffix }}
    </span>
    <div v-if="!readOnly" :class="styles.steppers">
      <!-- stepper -->
      <button v-bind="api.getDecrementTriggerProps()" :class="styles.stepper">
        <Icon name="down" :size="size" />
      </button>
      <!-- stepper -->
      <button v-bind="api.getIncrementTriggerProps()" :class="styles.stepper">
        <Icon name="up" :size="size" />
      </button>
    </div>
    <input
      v-if="name !== undefined"
      type="hidden"
      :name="name"
      :value="committed ?? ''"
      :disabled="disabled || undefined"
    />
  </div>
</template>
